import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.CliRSA9F.js";const s="/images/feed_health_check_speed.webp",p=JSON.parse('{"title":"Distribution Health","description":"","frontmatter":{},"headers":[],"relativePath":"features/distribution-health.md","filePath":"features/distribution-health.md"}'),i={name:"features/distribution-health.md"};function n(h,e,d,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="distribution-health" tabindex="-1">Distribution Health <a class="header-anchor" href="#distribution-health" aria-label="Permalink to &quot;Distribution Health&quot;">​</a></h1><h2 id="make-sure-every-app-and-directory-can-find-your-show" tabindex="-1">Make Sure Every App and Directory Can Find Your Show <a class="header-anchor" href="#make-sure-every-app-and-directory-can-find-your-show" aria-label="Permalink to &quot;Make Sure Every App and Directory Can Find Your Show&quot;">​</a></h2><p>Distribution Health gives you a complete picture of where your podcast is listed and whether each of those listings is healthy. Your RSS feed is the single file every podcast directory reads, so when it works well your episodes show up everywhere they should — and when something goes wrong, it can quietly affect every app at once. This page helps you confirm your feed is sound, see where your show is distributed, and catch problems before they cost you listeners.</p><p><img src="'+s+'" alt="Distribution Health" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Navigate to <strong>Traction</strong> in the sidebar, then select the <strong>Distribution</strong> tab.</p><hr><h2 id="your-feed-and-where-you-re-listed" tabindex="-1"><strong>Your Feed and Where You&#39;re Listed</strong> <a class="header-anchor" href="#your-feed-and-where-you-re-listed" aria-label="Permalink to &quot;**Your Feed and Where You&#39;re Listed**&quot;">​</a></h2><p>A row of shortcuts at the top of the page jumps straight to each section: Feed, Website, Primary distribution, Grow your reach, App and directory links, and — when available — Share your show and Reach more listeners.</p><h3 id="distribution-health-warning" tabindex="-1"><strong>Distribution Health Warning</strong> <a class="header-anchor" href="#distribution-health-warning" aria-label="Permalink to &quot;**Distribution Health Warning**&quot;">​</a></h3><p>If something needs attention, a warning banner appears above everything else. It explains the problem in plain terms (for example, a feed issue or a missing platform) and shows an <strong>X% health</strong> badge. The percentage reflects whether your show is listed on the four major apps — Apple Podcasts, Spotify, Amazon Music, and YouTube Music — and whether your RSS feed responds correctly. Any platform that isn&#39;t available for your show is left out of the calculation. When everything is in place, the banner disappears. Use the button in the banner to jump straight to the feed check.</p><h3 id="feed" tabindex="-1"><strong>Feed</strong> <a class="header-anchor" href="#feed" aria-label="Permalink to &quot;**Feed**&quot;">​</a></h3><p>Your <strong>Feed</strong> is the RSS file every directory pulls from. PodSEO shows your primary feed along with any alternate or redirected feeds it detects, each with a status indicator so you can tell at a glance whether things look healthy or need attention. Having a single, clean primary feed matters: alternate or duplicate feeds can split your stats and confuse directories about which version to follow.</p><p>Under the feed, a freshness panel shows when PodSEO last read your feed and what it currently has on file — <strong>Title</strong>, <strong>Author</strong>, <strong>Description</strong>, <strong>Episodes</strong>, and <strong>Latest episode</strong>. If you just changed something at your host and don&#39;t see it reflected in PodSEO yet, compare these values with what you published, then click <strong>Read it again</strong> to ask PodSEO to re-read your feed. The new values appear within a few minutes.</p><h3 id="website" tabindex="-1"><strong>Website</strong> <a class="header-anchor" href="#website" aria-label="Permalink to &quot;**Website**&quot;">​</a></h3><p>Your <strong>Website</strong> is your show&#39;s home on the web, detected from your RSS feed. A dedicated website is one of the biggest discoverability levers you control, because it&#39;s the only place your show gets Google-indexed pages and a custom domain that no platform can lock away. If PodSEO doesn&#39;t find a custom website (or your feed only points at a hosting or directory page), it flags that here so you know there&#39;s an opportunity to claim that ground.</p><h3 id="primary-distribution" tabindex="-1"><strong>Primary Distribution</strong> <a class="header-anchor" href="#primary-distribution" aria-label="Permalink to &quot;**Primary Distribution**&quot;">​</a></h3><p><strong>Primary distribution</strong> covers the four apps where most podcast listening happens: Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Each platform gets a row with a status indicator:</p><ul><li><strong>Green</strong> — PodSEO found one listing for your show</li><li><strong>Amber</strong> — PodSEO found more than one active listing. A warning explains that multiple listings usually mean duplicates, which split your rankings and reviews. Contact that platform&#39;s support to merge them where possible.</li><li><strong>Red</strong> — no listing found yet. Expand the row and use <strong>Add URL manually</strong> to paste the public page for your show on that platform.</li></ul><p>If you paste your own listing and it was previously attached to an old podcast that has since been deleted from PodSEO, it&#39;s now linked to your show straight away.</p><h3 id="grow-your-reach" tabindex="-1"><strong>Grow Your Reach</strong> <a class="header-anchor" href="#grow-your-reach" aria-label="Permalink to &quot;**Grow Your Reach**&quot;">​</a></h3><p><strong>Grow your reach</strong> lists additional directories that use their own show pages. Check each one for your show and save the link you find so it&#39;s handy. Some of these directories import feeds automatically; others accept submissions. PodSEO keeps the links you save but doesn&#39;t independently verify or monitor them.</p><h3 id="app-and-directory-links" tabindex="-1"><strong>App and Directory Links</strong> <a class="header-anchor" href="#app-and-directory-links" aria-label="Permalink to &quot;**App and Directory Links**&quot;">​</a></h3><p><strong>App and directory links</strong> gives you ready-made links to open your show in more podcast apps and directories. These are generated from your show&#39;s details, so check a link before sharing it widely.</p><h3 id="share-your-show" tabindex="-1"><strong>Share Your Show</strong> <a class="header-anchor" href="#share-your-show" aria-label="Permalink to &quot;**Share Your Show**&quot;">​</a></h3><p>When available, <strong>Share your show</strong> lists smart links — a single URL that sends each listener to the podcast app they use. They&#39;re ideal for your social bios, email signature, and show notes, so you don&#39;t have to maintain a list of app buttons yourself.</p><h3 id="reach-more-listeners" tabindex="-1"><strong>Reach More Listeners</strong> <a class="header-anchor" href="#reach-more-listeners" aria-label="Permalink to &quot;**Reach More Listeners**&quot;">​</a></h3><p>When relevant, <strong>Reach more listeners</strong> suggests regional and niche directories that serve specific languages, countries, or audiences. PodSEO doesn&#39;t track these, so open them directly and submit your show if it fits their audience.</p><hr><h2 id="feed-analysis" tabindex="-1"><strong>Feed Analysis</strong> <a class="header-anchor" href="#feed-analysis" aria-label="Permalink to &quot;**Feed Analysis**&quot;">​</a></h2><p>Expand <strong>Check feed health</strong> and click <strong>Run feed check</strong> to run a full read of your RSS feed. Run it again whenever you want to re-test your feed. The analysis validates how your feed is built and surfaces anything that could trip up the apps that rely on it.</p><h3 id="feed-status-and-health-checklist" tabindex="-1"><strong>Feed Status and Health Checklist</strong> <a class="header-anchor" href="#feed-status-and-health-checklist" aria-label="Permalink to &quot;**Feed Status and Health Checklist**&quot;">​</a></h3><p>The analysis leads with a clear <strong>Well-Formed</strong> or <strong>Malformed</strong> status, then a short pass/fail checklist covering the essentials:</p><ul><li><strong>Well-formed XML</strong> — Confirms your feed is structured correctly so directories can read it</li><li><strong>Valid Episodes</strong> — How many of your episodes are valid out of the total found in the feed</li><li><strong>Podcast 2.0 Tags</strong> — Whether your feed uses the newer Podcast 2.0 tags that unlock richer features in modern apps</li><li><strong>Feed Size</strong> — The overall size of your feed file</li></ul><p>You&#39;ll also see a quick <strong>Feed Statistics</strong> summary of your total and valid episode counts, and — when present — the specific Podcast 2.0 features your feed includes.</p><h3 id="issues-found" tabindex="-1"><strong>Issues Found</strong> <a class="header-anchor" href="#issues-found" aria-label="Permalink to &quot;**Issues Found**&quot;">​</a></h3><p>Rather than reducing everything to a single number, Distribution Health tells you exactly what needs attention by listing the specific <strong>Issues Found</strong> in your feed, grouped into:</p><ul><li><strong>Errors</strong> — Problems that can prevent your feed from being read or distributed correctly, which should be fixed first</li><li><strong>Warnings</strong> — Less urgent issues worth reviewing and cleaning up over time</li></ul><p>Each entry describes the issue directly so you know what to take to your podcast host. If your feed is clean, you simply won&#39;t see any errors or warnings — that&#39;s a good sign.</p><hr><h2 id="feed-fetch-performance" tabindex="-1"><strong>Feed Fetch Performance</strong> <a class="header-anchor" href="#feed-fetch-performance" aria-label="Permalink to &quot;**Feed Fetch Performance**&quot;">​</a></h2><p>A core part of this page is the <strong>Feed Fetch Performance</strong> panel, which measures how quickly your feed actually loads — and what it has to go through to get there.</p><p>Every analytics tracker or ad-insertion service you add to your feed creates a redirect — an extra hop between a directory requesting your feed and actually receiving it. Stacking multiple redirects slows things down, inflates your feed size, and can cause failures on some platforms.</p><p>This panel shows:</p><ul><li><strong>Initial and final URL</strong> — Where the request starts and where it ends up after any redirects</li><li><strong>Redirect chain</strong> — Each hop in the chain, with its response status and the time that hop took, so you can see exactly where delay is being introduced</li><li><strong>Total time</strong> — How long the whole fetch took from start to finish</li><li><strong>Feed size</strong> — Your feed file size, graded so you can tell at a glance whether it&#39;s a good size, getting large, or too large</li><li><strong>Redirects</strong> — The total number of hops in the chain</li></ul><p>If you see a long redirect chain or slow total time, review which tracking services are still necessary and remove any you no longer use. For a deeper look at why this matters, see our academy article on <a href="/academy/why-multiple-podcast-trackers-are-a-recipe-for-disaster.html">why multiple podcast trackers are a recipe for disaster</a>.</p><hr><h2 id="how-to-use-distribution-health" tabindex="-1"><strong>How to Use Distribution Health</strong> <a class="header-anchor" href="#how-to-use-distribution-health" aria-label="Permalink to &quot;**How to Use Distribution Health**&quot;">​</a></h2><ol><li><strong>Start with the feed status.</strong> Confirm your feed reads as Well-Formed and that your valid episode count matches what you expect. A Malformed feed is the most important thing to fix.</li><li><strong>Work through any errors, then warnings.</strong> Errors can block distribution, so address those first; warnings are cleanup you can schedule.</li><li><strong>Check your fetch performance.</strong> If your total fetch time is high or your redirect chain is long, trim trackers you no longer need and consider whether your feed size is creeping into &quot;large&quot; territory.</li><li><strong>Confirm your platform listings and website.</strong> Make sure each Primary distribution row is green, add any missing listing with <strong>Add URL manually</strong>, merge duplicate listings, and claim a custom website if you don&#39;t have one yet.</li><li><strong>Take fixes to your host.</strong> Many feed-level changes are made through your podcast hosting platform, so use the specific issues listed here as your checklist when you update your settings.</li></ol><hr><h2 id="best-practices-for-distribution-health" tabindex="-1"><strong>Best Practices for Distribution Health</strong> <a class="header-anchor" href="#best-practices-for-distribution-health" aria-label="Permalink to &quot;**Best Practices for Distribution Health**&quot;">​</a></h2><h3 id="check-after-changes" tabindex="-1"><strong>Check After Changes</strong> <a class="header-anchor" href="#check-after-changes" aria-label="Permalink to &quot;**Check After Changes**&quot;">​</a></h3><p>Revisit Distribution Health after you change your hosting setup, update metadata, or add or remove a tracker. This is the fastest way to confirm a change had the effect you intended and didn&#39;t introduce a new issue.</p><h3 id="keep-your-redirect-chain-short" tabindex="-1"><strong>Keep Your Redirect Chain Short</strong> <a class="header-anchor" href="#keep-your-redirect-chain-short" aria-label="Permalink to &quot;**Keep Your Redirect Chain Short**&quot;">​</a></h3><p>Each tracker you stack onto your feed adds time and size. Periodically prune services you no longer use — a shorter chain means faster loads and fewer chances for playback failures.</p><h3 id="consolidate-to-a-single-clean-feed" tabindex="-1"><strong>Consolidate to a Single Clean Feed</strong> <a class="header-anchor" href="#consolidate-to-a-single-clean-feed" aria-label="Permalink to &quot;**Consolidate to a Single Clean Feed**&quot;">​</a></h3><p>Multiple active or duplicate feeds can split your stats and send directories to the wrong place. Aim for one clear primary feed that every app follows.</p><h3 id="claim-your-own-website" tabindex="-1"><strong>Claim Your Own Website</strong> <a class="header-anchor" href="#claim-your-own-website" aria-label="Permalink to &quot;**Claim Your Own Website**&quot;">​</a></h3><p>If Distribution Health flags a missing custom website, it&#39;s worth acting on. A dedicated site gives your show indexed pages and a presence that doesn&#39;t depend on any single platform.</p><hr><h2 id="working-with-other-podseo-features" tabindex="-1"><strong>Working with Other PodSEO Features</strong> <a class="header-anchor" href="#working-with-other-podseo-features" aria-label="Permalink to &quot;**Working with Other PodSEO Features**&quot;">​</a></h2><p>A healthy, fast-loading feed supports everything else you do in PodSEO. Clean metadata strengthens the keyword work you do in <a href="/features/keyword-strategy.html">Keyword Strategy</a>, and reliable distribution underpins the discoverability you track in <a href="/features/visibility-progress.html">Visibility Progress</a>. You can also see a quick distribution summary on the <a href="/features/podcast-details.html">Overview</a> tab, with a link straight back into this tab when you want the full diagnostic.</p><hr><p><strong>Getting Started</strong>: Open the <strong>Distribution</strong> tab, expand <strong>Check feed health</strong>, click <strong>Run feed check</strong>, and review your feed status, any issues found, and your fetch performance. Use the specific issues listed there as a checklist when you make changes through your podcast host.</p>',63)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
